import 'package:hive_flutter/hive_flutter.dart';class PinService {  static const String _msgBoxName = 'pinned_messages';  static const String _chatBoxName = 'pinned_chats';  Box? _msgBox;  Box? _chatBox;  Future<void> initialize() async {    _msgBox = await Hive.openBox(_msgBoxName);    _chatBox = await Hive.openBox(_chatBoxName);  }  Future<void> pinMessage(String chatId, String messageId,      Map<String, dynamic> messagePreview) async {    final key = '${chatId}_$messageId';    await _msgBox?.put(key, {      'chatId': chatId,      'messageId': messageId,      'preview': messagePreview,      'pinnedAt': DateTime.now().toIso8601String(),    });  }  Future<void> unpinMessage(String chatId, String messageId) async {    final key = '${chatId}_$messageId';    await _msgBox?.delete(key);  }  List<Map<String, dynamic>> getPinnedMessages(String chatId) {    final messages = <Map<String, dynamic>>[];    final box = _msgBox;    if (box == null) return messages;    for (final key in box.keys) {      if (key.toString().startsWith('${chatId}_')) {        final data = box.get(key);        if (data != null) {          messages.add(Map<String, dynamic>.from(data));        }      }    }    return messages;  }  bool isMessagePinned(String chatId, String messageId) {    final key = '${chatId}_$messageId';    return _msgBox?.containsKey(key) ?? false;  }  Future<void> pinChat(String chatId) async {    await _chatBox?.put(chatId, {      'chatId': chatId,      'pinnedAt': DateTime.now().toIso8601String(),    });  }  Future<void> unpinChat(String chatId) async {    await _chatBox?.delete(chatId);  }  bool isChatPinned(String chatId) {    return _chatBox?.containsKey(chatId) ?? false;  }  List<String> getPinnedChatIds() {    return _chatBox?.keys.cast<String>().toList() ?? [];  }  Future<void> clearAllPins(String chatId) async {    final box = _msgBox;    if (box == null) return;    final keysToDelete = <String>[];    for (final key in box.keys) {      if (key.toString().startsWith('${chatId}_')) {        keysToDelete.add(key.toString());      }    }    for (final key in keysToDelete) {      await box.delete(key);    }  }}